INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 17, 'theory', 'Quiz: the relational model and queries');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 17, 0, 'The query WHERE city = NULL returned nothing, although the table has customers with no city. Why?', '["NULL must be written in lowercase", "Comparing with NULL gives \"unknown\", not true: you need IS NULL", "The city column has the wrong type", "WHERE cannot work with strings"]', 1, 'NULL means "not set"; any comparison with it is UNKNOWN, and such rows are dropped. To test for it, use IS NULL and IS NOT NULL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 17, 1, 'What will a query with the condition x NOT IN (1, 2, NULL) return?', '["All rows where x is not 1 and not 2", "An error: NULL is not allowed in the list", "Only the rows where x is NULL", "No rows: for any x the condition is UNKNOWN"]', 3, 'x <> NULL is unknown, and a conjunction with unknown is never true. So NOT IN with a NULL in the list is always empty; use NOT EXISTS or remove the NULL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 17, 2, 'After LEFT JOIN orders you added WHERE orders.status = ''paid'', and customers without orders disappeared. What happened?', '["The rows with NULL on the right failed the condition, and the join effectively became an inner one", "LEFT JOIN cannot be combined with WHERE", "The database deleted the customers without orders", "The condition was applied to the left table"]', 0, 'For a customer without orders, orders.status is NULL, and NULL = ''paid'' is unknown. A condition on the right table that must not remove left rows goes into ON.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 17, 3, 'After joining an order with its items and payments, the order total came out three times too big. What is the right fix?', '["Apply DISTINCT to the whole sum", "Replace JOIN with LEFT JOIN", "Collapse the items and payments separately into one row per order and only then join", "Add ORDER BY before SUM"]', 2, 'Every join multiplies rows, and the aggregate counts the duplicates. First aggregate each branch (a subquery or WITH), then join the results.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 17, 4, 'What is the difference between WHERE and HAVING?', '["None, they are synonyms", "WHERE filters rows before grouping, HAVING filters groups after it and can use aggregates", "HAVING works only with numbers", "WHERE is faster on any data"]', 1, 'Logical order: FROM → WHERE → GROUP BY → HAVING → SELECT. That is why an aggregate is not allowed in WHERE but is allowed in HAVING.');
